const pb = global.get("pb");
let messages = msg.payload;

if (!Array.isArray(messages)) messages = [messages];

messages.forEach(entry => {
    if (!entry.target) {
        entry.target = entry.client === "rayvn" ? "wasos" : "rayvn";
    }
    if (!entry.connection_id && msg.connection) {
        entry.connection_id = msg.connection.id;
    }
    pb.enqueue(entry);
});

// Lagre target for Send-funksjonen
if (messages[0]) flow.set("queue_target", messages[0].target);

// Trigger send kun etter siste melding i batch
if (msg.parts && msg.parts.index !== msg.parts.count - 1) {
    return null;
}

return msg;

const pb = global.get("pb");

let dequeued = pb.dequeue(msg.msg_id);

msg.payload = dequeued ? [dequeued] : [];
return msg;

const pb = global.get("pb");
const target = flow.get("queue_target");

if (!target) { node.warn("No queue target"); return null; }

let queue = pb.getQueue(target);

if (queue.length <= 0) {
    context.set("sending", false);
    return null;
}

if (msg.topic === "response") {
    context.set("sending", false);
}

if (context.get("sending")) return null;

context.set("sending", true);
let entry = queue[0];
msg.msg_id = entry.id;
msg.payload = [entry];
msg.connection = pb.getConnection(entry.connection_id);

return msg;

