const pb = global.get("pb");

let retry_limit = context.get("retry_limit") || 5;
let current_id = context.get("current_id");
let retries = context.get("retries") || 0;

if (!current_id || current_id !== msg.msg_id) {
    context.set("current_id", msg.msg_id);
    context.set("retries", 1);
    pb.incrementRetry(msg.msg_id, "HTTP " + (msg.statusCode || "unknown"));
    return [null, msg];
}

retries = context.get("retries");

if (retries < retry_limit) {
    context.set("retries", retries + 1);
    pb.incrementRetry(msg.msg_id, "HTTP " + (msg.statusCode || "unknown"));
    return [null, msg];
} else {
    let failed = pb.dequeue(msg.msg_id);
    if (failed) {
        pb.addToMasterLog(failed, "failed");
    }
    context.set("retries", 0);
    context.set("current_id", "");
    msg.failed_messages = failed ? [failed] : [];
    return [msg, null];
}

